TomoMod_RegisterLocale("enUS", {
    ["info_key_shortcuts_title"] = "Mythic keystone shortcuts",
    ["info_key_shortcuts_left"] = "Left click: announce party keys (/tmt key)",
    ["info_key_shortcuts_right"] = "Right click: open Keystone Roulette (/tm key)",
    ["key_roulette_title"] = "KEYSTONE ROULETTE",
    ["key_roulette_subtitle"] = "Randomly choose one of the party keystones",
    ["key_roulette_spin"] = "SPIN THE ROULETTE",
    ["key_roulette_ready"] = "Ready to choose a keystone",
    ["key_roulette_refreshing"] = "Refreshing party keystones...",
    ["key_roulette_empty"] = "No party keystones received yet",
    ["info_auras_all_disables_enemy_buffs"] = "Target Buffs is disabled while Auras shows both buffs and debuffs to prevent duplicate icons.",
    ["wn_407_keystone_shortcut"] = "New — A keystone shortcut now appears beside the minimap clock in 2-5 player groups. Left-click announces party keys with /tmt key, while right-click opens Keystone Roulette with /tm key.",
    ["wn_407_keystone_roulette"] = "Changed — Keystone Roulette now uses TomoMod's brand palette, full dungeon names, class-colored owners, clearer key levels, animated selection and a dedicated result card. It opens immediately while KeySync refreshes party data.",
    ["wn_407_keystone_localization"] = "Changed — Keystone shortcut tooltips and every Roulette state are localized in English, French, German, Spanish, Italian and Brazilian Portuguese.",
    ["wn_407_keystone_layout"] = "Fixed — When the addon-button collector is docked to the left of the minimap clock, the keystone shortcut moves farther left and keeps a visible gap. Its position accounts for the collector's scale and the Consumable Tracker, so the buttons no longer overlap. Its icon is now white like the other InfoPanel buttons.",
    ["wn_407_unitframe_configuration"] = "Fixed — TomoLayout's Configure Element action now opens Astral Forge for every selectable UnitFrame, including Player, Target, Focus, Pet, Target of Target and Boss Frames.",
    ["wn_407_astralforge_subject"] = "Changed — Astral Forge now receives the selected UnitFrame as its launch subject and opens directly on the chosen frame instead of reusing the previous subject.",
    ["wn_407_layout_studio_routing"] = "Fixed — TomoLayout now selects Party and Raid mover overlays correctly. Configure Element opens Resource & Cast Studio for Resources and Player Cast, or Party & Raid Studio for Party and Raid, directly on the matching view.",
    ["wn_407_astral_aura_controls"] = "New — The Auras element in Astral Forge can display buffs, debuffs or both, with 1 to 12 icons. Target Buffs has the same 12-icon limit and is disabled automatically when Auras already shows both types.",
    ["wn_407_raid_position_restore"] = "Fixed — The Raid Frames position saved in TomoLayout is now restored when the addon initializes. Reloading the UI or logging back in no longer returns the raid layout to its default position.",
    ["wn_407_resource_text_layer"] = "Fixed — Resource values now render above bar fills, class-power segments, tick marks and borders, keeping point counts and rune cooldown numbers visible.",
    ["wn_407_secret_value_guards"] = "Fixed — Bar 1 page remapping and segmented, partial or texture-band resources now reject secret action-slot and UnitPower values before Lua comparisons or arithmetic, preventing restricted-content errors.",
    ["wn_407_vehicle_actionbar_visuals"] = "Fixed — Vehicle, override and possess transitions now rebuild Bar 1's action-slot mapping and repaint its buttons through the same complete page-change path. Retail vehicles no longer leave working keybinds attached to invisible or stale buttons when UPDATE_VEHICLE_ACTIONBAR fires without UPDATE_OVERRIDE_ACTIONBAR.",
})

TomoMod_RegisterLocale("frFR", {
